using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 侵蚀技能夺取弹窗 — 全局暂停时显示敌人技能列表，供玩家选择夺取/升级。
/// UI 结构由预制体预设；运行时只动态填充技能槽。
/// </summary>
public class SkillStealPopupManager : MonoBehaviour
{
    public static SkillStealPopupManager Instance { get; private set; }

    [Header("预制体")]
    [SerializeField] private SkillSlotView _slotPrefab;

    [Header("弹窗 UI（预制体中预设）")]
    [SerializeField] private GameObject _backdrop;
    [SerializeField] private GameObject _popupPanel;
    [SerializeField] private Transform _slotContainer;
    [SerializeField] private Text _titleText;
    [SerializeField] private Text _cancelText;
    [SerializeField] private Button _cancelButton;

    private Font _runtimeFont;
    private IReadOnlyList<SkillInstance> _enemySkills;
    private PlayerSkillManager _playerSkillManager;
    private Action _onClose;
    private bool _isShowing;

    private void Awake()
    {
        if (Instance == null)
            Instance = this;
        else
            Destroy(gameObject);

        // 动态字体无法被预制体序列化，运行时创建
        _runtimeFont = Font.CreateDynamicFontFromOSFont("Arial", 16);

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);
    }

    private void OnDestroy()
    {
        // 切换场景时清理单例
        if (Instance == this)
            Instance = null;
    }

    public void ShowPopup(IReadOnlyList<SkillInstance> enemySkills, PlayerSkillManager player, Action onClose)
    {
        if (_isShowing) return;
        _isShowing = true;

        _enemySkills = enemySkills;
        _playerSkillManager = player;
        _onClose = onClose;

        if (_popupPanel == null) { _isShowing = false; return; }

        if (_titleText != null)
        {
            _titleText.font = _runtimeFont;
            _titleText.text = "选择要夺取的技能";
        }

        if (_cancelText != null)
            _cancelText.font = _runtimeFont;

        // 清理旧槽位
        for (int i = _slotContainer.childCount - 1; i >= 0; i--)
            Destroy(_slotContainer.GetChild(i).gameObject);

        // 动态生成技能槽
        for (int i = 0; i < enemySkills.Count; i++)
        {
            int captured = i;
            SkillInstance enemySkill = enemySkills[i];

            SkillSlotView slotView = Instantiate(_slotPrefab, _slotContainer);

            SkillViewData viewData = BuildSlotData(enemySkill);
            slotView.Refresh(viewData);

            // 点击 = 选择该技能
            Button slotBtn = slotView.GetComponent<Button>();
            if (slotBtn == null) slotBtn = slotView.gameObject.AddComponent<Button>();
            slotBtn.onClick.RemoveAllListeners();
            slotBtn.onClick.AddListener(() => OnSkillSelected(captured));
        }

        if (_cancelButton != null)
        {
            _cancelButton.onClick.RemoveAllListeners();
            _cancelButton.onClick.AddListener(ClosePopup);
        }

        if (_backdrop != null)
            _backdrop.SetActive(true);
        _popupPanel.SetActive(true);
    }

    private SkillViewData BuildSlotData(SkillInstance skill)
    {
        SkillViewData data = default;
        if (skill == null || skill.Data == null) return data;

        SkillData def = skill.Data;
        data.Icon = def.icon;
        data.Level = skill.Level;
        data.MaxLevel = skill.MaxLevel;
        data.IsEquipped = true;
        data.IsUnlocked = true;
        data.IsCoolingDown = false;
        data.ShowKeyLabel = false;  // 弹窗中隐藏键位标签

        bool hasSkill = PlayerHasSkill(def.skillId, out int playerLv, out _);
        if (hasSkill)
            data.KeyLabel = playerLv < skill.MaxLevel ? "升级" : "已满";
        else
            data.KeyLabel = HasEmptySlot() ? "新技能" : "无空槽";

        return data;
    }

    private bool HasEmptySlot()
    {
        for (int i = 0; i < _playerSkillManager.SlotCount; i++)
            if (_playerSkillManager.IsSlotUnlocked(i) && _playerSkillManager.GetSkill(i) == null)
                return true;
        return false;
    }

    private bool PlayerHasSkill(string skillId, out int level, out int slotIdx)
    {
        for (int i = 0; i < _playerSkillManager.SlotCount; i++)
        {
            SkillInstance skill = _playerSkillManager.GetSkill(i);
            if (skill != null && skill.Data.skillId == skillId)
            {
                level = skill.Level;
                slotIdx = i;
                return true;
            }
        }
        level = 0;
        slotIdx = -1;
        return false;
    }

    private void OnSkillSelected(int index)
    {
        if (index < 0 || index >= _enemySkills.Count) return;

        SkillInstance enemySkill = _enemySkills[index];
        string skillId = enemySkill.Data.skillId;

        if (PlayerHasSkill(skillId, out int playerLv, out int slotIdx))
        {
            if (playerLv < enemySkill.MaxLevel)
                _playerSkillManager.UpgradeSkill(slotIdx);
        }
        else
        {
            _playerSkillManager.AcquireSkill(skillId);
        }

        ClosePopup();
    }

    public void ClosePopup()
    {
        if (!_isShowing) return;
        _isShowing = false;

        if (_backdrop != null)
            _backdrop.SetActive(false);
        if (_popupPanel != null)
            _popupPanel.SetActive(false);

        _onClose?.Invoke();
        _onClose = null;
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 技能槽位 View —— 纯渲染，不引用任何游戏逻辑。
/// 由 Controller 调用 Refresh() 更新显示。
/// </summary>
public class SkillSlotView : MonoBehaviour
{
    [Header("图标与文本")]
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _keyLabel;
    [SerializeField] private TMP_Text _levelText;

    [Header("冷却")]
    [SerializeField] private Image _cooldownOverlay;
    [SerializeField] private TMP_Text _cooldownText;

    [Header("状态遮罩")]
    [SerializeField] private GameObject _lockedOverlay;
    [SerializeField] private GameObject _emptyOverlay;

    [Header("交互")]
    [SerializeField] private Button _upgradeButton;

    /// <summary>Controller 调用，传入数据刷新 UI</summary>
    public void Refresh(in SkillViewData data)
    {
        // 图标
        if (_icon != null)
        {
            _icon.sprite = data.Icon;
            _icon.enabled = data.Icon != null;
        }

        // 快捷键
        if (_keyLabel != null)
        {
            _keyLabel.text = data.KeyLabel;
            _keyLabel.gameObject.SetActive(data.ShowKeyLabel);
        }

        // 等级
        if (_levelText != null)
            _levelText.text = data.IsEquipped ? $"Lv.{data.Level}" : "";

        // 冷却填充 — 仅在冷却中显示，否则完全隐藏
        if (_cooldownOverlay != null)
        {
            _cooldownOverlay.fillAmount = data.CooldownPercent;
            _cooldownOverlay.enabled = data.IsCoolingDown && data.CooldownPercent > 0f;
        }

        // 冷却数字
        if (_cooldownText != null)
        {
            bool showCooldown = data.IsCoolingDown && data.CooldownRemaining > 0f;
            _cooldownText.gameObject.SetActive(showCooldown);
            if (showCooldown)
                _cooldownText.text = $"{data.CooldownRemaining:F1}s";
        }

        // 解锁/空槽遮罩
        if (_lockedOverlay != null)
            _lockedOverlay.SetActive(!data.IsUnlocked);
        if (_emptyOverlay != null)
            _emptyOverlay.SetActive(data.IsUnlocked && !data.IsEquipped);

        // 升级按钮 — 未装备或满级时隐藏
        if (_upgradeButton != null)
            _upgradeButton.gameObject.SetActive(data.IsEquipped && data.Level < data.MaxLevel);
    }
}

